mapper.update:
UPDATE reconciliation_cutoff SET collection_state='PENDING',collection_progress=CAST(#{progress} AS JSON),
 next_attempt_at=#{now},collection_error=NULL,version=version+1,updated_at=#{now}
WHERE enterprise_id=#{e} AND warehouse_id=#{w} AND cutoff_id=#{id} AND collection_state='UNREQUESTED' AND evidence_version=0

mapper.select:
SELECT c.command_id,c.action,c.state,c.business_effect_key,p.id AS posting_id,p.action AS posting_action,p.quantity,p.source_execution_id,p.created_at AS posted_at
FROM stock_command c LEFT JOIN stock_posting p ON p.enterprise_id=c.enterprise_id AND p.warehouse_id=c.warehouse_id
 AND p.source_service=c.source_service AND p.command_id=c.command_id
WHERE c.enterprise_id=#{e} AND c.warehouse_id=#{w} AND c.source_service=#{source}
 AND c.command_id IN #{command}

SELECT command_id FROM stock_posting WHERE enterprise_id=#{e} AND warehouse_id=#{w} AND source_service=#{source}
 AND created_at < #{cutoff} AND command_id > #{after}
ORDER BY command_id LIMIT 201

SELECT command_id,business_effect_key,quantity,occurred_at FROM source_execution_fact
WHERE enterprise_id=#{e} AND warehouse_id=#{w} AND source_service=#{source} AND fact_kind='PHYSICAL'
 AND command_id IN #{command}

mapper.update:
UPDATE reconciliation_cutoff c JOIN reconciliation_history_guard g ON g.enterprise_id=c.enterprise_id AND g.warehouse_id=c.warehouse_id
SET c.collection_state='COMPLETE',c.collection_progress=CAST(#{progress} AS JSON),c.evidence_version=1,c.watermarks_complete=1,
 c.source_watermark=#{source},c.posting_watermark=#{posting},c.receipt_watermark=#{receipt},c.collection_error=NULL,
 c.collection_attempts=0,c.version=c.version+1,c.updated_at=#{now}
WHERE c.enterprise_id=#{e} AND c.warehouse_id=#{w} AND c.cutoff_id=#{id} AND c.claim_epoch=#{epoch}
 AND c.collection_state='RUNNING' AND g.active_cutoff_id=#{id} AND g.closed_before >= c.closed_at
